import blur from "@/content/media/blur.json";
import manifest from "@/content/media/manifest.json";

const blurMap = blur as Record<string, string>;
type Entry = { dest: string; credit?: string; generated?: boolean; source?: string };
const entries = manifest as Entry[];

/** Tiny base64 placeholder for an image path, if one was generated by scripts/media/build-images.mjs. */
export function blurFor(src?: string): string | undefined {
  return src ? blurMap[src] : undefined;
}

/** True for technical drawings that stand in where there is no photograph. */
export function isIllustration(src?: string): boolean {
  if (!src) return false;
  return entries.some((e) => e.generated && src.startsWith(e.dest));
}

/** Attribution text for a third-party image that requires it. */
export function creditFor(src?: string): string | undefined {
  if (!src) return undefined;
  return entries.find((e) => e.credit && src.startsWith(e.dest))?.credit;
}
